compliant:
import { Effect, Schema } from "effect"

const Widget = Schema.Struct({
  id: Schema.String,
  column: Schema.Number,
  row: Schema.Number
})

export const DashboardLayout = Schema.Struct({
  title: Schema.String,
  widgets: Schema.Array(Widget)
})

export type DashboardLayout = typeof DashboardLayout.Type

export class InvalidLayoutJson extends Schema.TaggedErrorClass<InvalidLayoutJson>()(
  "InvalidLayoutJson",
  { path: Schema.String, cause: Schema.Unknown }
) {}

export const parseLayout = (path: string, text: string) =>
  Effect.gen(function*() {
    const value = yield* Effect.try({
      try: (): unknown => JSON.parse(text),
      catch: (cause) => InvalidLayoutJson.make({ path, cause })
    })
    const layout = yield* Schema.decodeUnknownEffect(DashboardLayout)(value)
    return { path, layout }
  })

export const parseLayouts = (
  files: ReadonlyArray<{ readonly path: string; readonly text: string }>
) =>
  Effect.forEach(files, ({ path, text }) => parseLayout(path, text), {
    concurrency: 4
  })
